{
  "findings": [
    {
      "check_id": "CKV_AZURE_13",
      "title": "Disabled critical security alerts",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "HIGH",
      "explanation": "Disabling critical alerts like 'Sql_Injection' and 'Data_Exfiltration' reduces the ability to detect and respond to potential security threats. These alerts should remain enabled to ensure comprehensive monitoring."
    },
    {
      "check_id": "CKV_AZURE_14",
      "title": "Insufficient retention period for security logs",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "A retention period of 20 days may not be sufficient for forensic investigations or compliance requirements. Increasing the retention period ensures logs are available for a longer duration."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key\n  disabled_alerts = []\n  retention_days  = 90\n  email_addresses = [\"securityengineer@bridgecrew.io\"]\n}",
  "fix_summary": "Enabled all critical security alerts by removing 'Sql_Injection' and 'Data_Exfiltration' from the disabled_alerts list. Increased the retention period for security logs from 20 days to 90 days to improve forensic and compliance capabilities."
}
